#![cfg(feature = "unstable")]

//! `Session::declarations_listener`: the remote subscribers and queryables a session holds, then
//! every declaration and undeclaration it receives, in the order received.

use std::time::Duration;

use zenoh::{
    declarations::{DeclarationEvent, DeclarationKind},
    handlers::FifoChannelHandler,
    Config, Session, Wait,
};
use zenoh_core::ztimeout;
use zenoh_test::get_free_tcp_port;

const TIMEOUT: Duration = Duration::from_secs(10);

/// Two peer sessions over TCP on the loopback, scouting off: the first listens, the second
/// connects to it.
async fn pair() -> (Session, Session) {
    let endpoint = format!("tcp/127.0.0.1:{}", get_free_tcp_port());
    let mut listening = Config::default();
    listening
        .insert_json5("listen/endpoints", &format!(r#"["{endpoint}"]"#))
        .unwrap();
    listening
        .insert_json5("scouting/multicast/enabled", "false")
        .unwrap();
    let mut connecting = Config::default();
    connecting
        .insert_json5("connect/endpoints", &format!(r#"["{endpoint}"]"#))
        .unwrap();
    connecting
        .insert_json5("scouting/multicast/enabled", "false")
        .unwrap();
    let listening = ztimeout!(zenoh::open(listening)).unwrap();
    let connecting = ztimeout!(zenoh::open(connecting)).unwrap();
    (listening, connecting)
}

async fn next(listener: &FifoChannelHandler<DeclarationEvent>) -> DeclarationEvent {
    ztimeout!(listener.recv_async()).unwrap()
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn a_listener_hears_a_remote_subscriber_declared_then_undeclared() {
    zenoh::init_log_from_env_or("error");
    let (session, remote) = pair().await;
    let listener = ztimeout!(session.declarations_listener()).unwrap();

    let subscriber = ztimeout!(remote.declare_subscriber("test/declared")).unwrap();
    let declared = next(&listener).await;
    assert_eq!(declared.kind(), DeclarationKind::Subscriber);
    assert_eq!(declared.key_expr().as_str(), "test/declared");
    assert!(declared.is_declared());

    ztimeout!(subscriber.undeclare()).unwrap();
    let undeclared = next(&listener).await;
    assert_eq!(undeclared.kind(), DeclarationKind::Subscriber);
    assert_eq!(undeclared.id(), declared.id());
    assert_eq!(undeclared.key_expr().as_str(), "test/declared");
    assert!(!undeclared.is_declared());

    ztimeout!(remote.close()).unwrap();
    ztimeout!(session.close()).unwrap();
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn a_listener_hears_a_remote_queryable_and_whether_it_is_complete() {
    zenoh::init_log_from_env_or("error");
    let (session, remote) = pair().await;
    let listener = ztimeout!(session.declarations_listener()).unwrap();

    let _complete = ztimeout!(remote.declare_queryable("test/complete").complete(true)).unwrap();
    let event = next(&listener).await;
    assert_eq!(event.kind(), DeclarationKind::Queryable { complete: true });
    assert_eq!(event.key_expr().as_str(), "test/complete");
    assert!(event.is_declared());

    let partial = ztimeout!(remote.declare_queryable("test/partial").complete(false)).unwrap();
    let declared = next(&listener).await;
    assert_eq!(
        declared.kind(),
        DeclarationKind::Queryable { complete: false }
    );
    assert_eq!(declared.key_expr().as_str(), "test/partial");

    ztimeout!(partial.undeclare()).unwrap();
    let undeclared = next(&listener).await;
    assert_eq!(
        undeclared.kind(),
        DeclarationKind::Queryable { complete: false }
    );
    assert_eq!(undeclared.id(), declared.id());
    assert!(!undeclared.is_declared());

    ztimeout!(remote.close()).unwrap();
    ztimeout!(session.close()).unwrap();
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn a_listener_registered_after_a_declaration_hears_it_first() {
    zenoh::init_log_from_env_or("error");
    let (session, remote) = pair().await;
    let first = ztimeout!(session.declarations_listener()).unwrap();
    let _subscriber = ztimeout!(remote.declare_subscriber("test/earlier")).unwrap();
    // The session holds the declaration once the first listener has heard it.
    assert_eq!(next(&first).await.key_expr().as_str(), "test/earlier");

    let later = ztimeout!(session.declarations_listener()).unwrap();
    let _queryable = ztimeout!(remote.declare_queryable("test/later")).unwrap();
    let current = next(&later).await;
    assert_eq!(current.key_expr().as_str(), "test/earlier");
    assert!(current.is_declared());
    assert_eq!(next(&later).await.key_expr().as_str(), "test/later");

    ztimeout!(remote.close()).unwrap();
    ztimeout!(session.close()).unwrap();
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn a_dropped_listener_hears_nothing_more() {
    zenoh::init_log_from_env_or("error");
    let (session, remote) = pair().await;
    let (sender, receiver) = flume::bounded(32);
    let dropped = ztimeout!(session
        .declarations_listener()
        .with((sender, receiver.clone())))
    .unwrap();
    let kept = ztimeout!(session.declarations_listener()).unwrap();
    drop(dropped);

    let _subscriber = ztimeout!(remote.declare_subscriber("test/after")).unwrap();
    assert_eq!(next(&kept).await.key_expr().as_str(), "test/after");
    assert!(matches!(
        receiver.try_recv(),
        Err(flume::TryRecvError::Disconnected)
    ));

    ztimeout!(remote.close()).unwrap();
    ztimeout!(session.close()).unwrap();
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn a_listener_does_not_hear_its_own_sessions_declarations() {
    zenoh::init_log_from_env_or("error");
    let (session, remote) = pair().await;
    let listener = ztimeout!(session.declarations_listener()).unwrap();

    let _own = ztimeout!(session.declare_subscriber("test/own")).unwrap();
    let _remote = ztimeout!(remote.declare_subscriber("test/remote")).unwrap();
    assert_eq!(next(&listener).await.key_expr().as_str(), "test/remote");

    ztimeout!(remote.close()).unwrap();
    ztimeout!(session.close()).unwrap();
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn a_listener_hears_once_a_declaration_the_session_already_holds() {
    zenoh::init_log_from_env_or("error");
    let (session, remote) = pair().await;
    let publisher = ztimeout!(session.declare_publisher("test/held")).unwrap();
    let matching = ztimeout!(publisher.matching_listener()).unwrap();
    let _held = ztimeout!(remote.declare_subscriber("test/held")).unwrap();
    // The session holds the declaration once its publisher matches it.
    while !ztimeout!(matching.recv_async()).unwrap().matching() {}

    let listener = ztimeout!(session.declarations_listener()).unwrap();
    let _next = ztimeout!(remote.declare_subscriber("test/next")).unwrap();
    assert_eq!(next(&listener).await.key_expr().as_str(), "test/held");
    assert_eq!(next(&listener).await.key_expr().as_str(), "test/next");

    ztimeout!(remote.close()).unwrap();
    ztimeout!(session.close()).unwrap();
}

