#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn a_listener_declared_after_the_last_was_dropped_hears_declarations() {
    zenoh::init_log_from_env_or("error");
    let (session, remote) = pair().await;
    let first = ztimeout!(session.declarations_listener()).unwrap();
    let _before = ztimeout!(remote.declare_subscriber("test/before")).unwrap();
    assert_eq!(next(&first).await.key_expr().as_str(), "test/before");
    drop(first);

    let second = ztimeout!(session.declarations_listener()).unwrap();
    assert_eq!(next(&second).await.key_expr().as_str(), "test/before");
    let _after = ztimeout!(remote.declare_subscriber("test/after")).unwrap();
    assert_eq!(next(&second).await.key_expr().as_str(), "test/after");

    ztimeout!(remote.close()).unwrap();
    ztimeout!(session.close()).unwrap();
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn a_callback_may_declare_on_its_own_session() {
    zenoh::init_log_from_env_or("error");
    let (session, remote) = pair().await;
    let (sender, receiver) = flume::unbounded();
    let own = session.clone();
    // The callback runs outside the session's state lock, which declaring a publisher takes.
    let _listener = ztimeout!(session.declarations_listener().callback(move |event| {
        let publisher = own.declare_publisher(event.key_expr().clone()).wait();
        sender.send((event, publisher)).unwrap();
    }))
    .unwrap();

    let _subscriber = ztimeout!(remote.declare_subscriber("test/callback")).unwrap();
    let (event, publisher) = ztimeout!(receiver.recv_async()).unwrap();
    assert_eq!(event.key_expr().as_str(), "test/callback");
    assert!(publisher.is_ok());

    ztimeout!(remote.close()).unwrap();
    ztimeout!(session.close()).unwrap();
}
